sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float reds;
uniform float yellows;
uniform float greens;
uniform float cyans;
uniform float blues;
uniform float magentas;
uniform float contrast;
layout(color) uniform half4 tintColor;
uniform float tintAmount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 rgb2hsv(float3 c) {
    float4 K = float4(0.0, -0.3333333, 0.6666667, -1.0);
    float4 p = mix(float4(c.b, c.g, K.w, K.z), float4(c.g, c.b, K.x, K.y), step(c.b, c.g));
    float4 q = mix(float4(p.x, p.y, p.w, c.r), float4(c.r, p.y, p.z, p.x), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + 0.0000001)), d / (q.x + 0.0000001), q.x);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 h = rgb2hsv(s);
    float wsum = 0.0;
    wsum += reds * saturate(1.0 - abs(fract(h.x + 0.5) - 0.5) * 6.0);
    wsum += yellows * saturate(1.0 - abs(fract(h.x - 0.1666667 + 0.5) - 0.5) * 6.0);
    wsum += greens * saturate(1.0 - abs(fract(h.x - 0.3333333 + 0.5) - 0.5) * 6.0);
    wsum += cyans * saturate(1.0 - abs(fract(h.x - 0.5 + 0.5) - 0.5) * 6.0);
    wsum += blues * saturate(1.0 - abs(fract(h.x - 0.6666667 + 0.5) - 0.5) * 6.0);
    wsum += magentas * saturate(1.0 - abs(fract(h.x - 0.8333333 + 0.5) - 0.5) * 6.0);
    float l = luma(s);
    float g = mix(l, l * wsum, saturate(h.y * 2.0));
    g = (g - 0.5) * contrast + 0.5;
    float3 gray = float3(g);
    float3 o = mix(gray, gray * float3(tintColor.rgb) * 1.8, tintAmount);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
